grep -n 'LOA_STATUS_ENV_DIR' -B2 -A4 .claude/scripts/loa-status.sh | head -30; echo ---; python3 -c "
import json;s=json.load(open('.claude/data/schemas/model-config-v3.schema.json'))
def walk(o,p=''):
    if isinstance(o,dict):
        for k,v in o.items():
            if k=='default_effort': print('default_effort at',p)
            walk(v,p+'/'+k)
    elif isinstance(o,list):
        for i,v in enumerate(o): walk(v,p+'/'+str(i))
walk(s)"; echo ---; grep -n '^[a-z_]*:' .claude/defaults/model-config.yaml | head -20; echo ---; sed -n 470,530p .claude/defaults/model-config.yaml

